46	func withTenantAuth(next http.Handler) http.Handler {
47		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
48			jwksOnce.Do(initJWKS)
49	
50			tenantID := ""
51	
52			if auth := r.Header.Get("Authorization"); strings.HasPrefix(auth, "Bearer ") {
53				token := strings.TrimPrefix(auth, "Bearer ")
54				if jwksFunc != nil {
55					if tid := verifyAndExtractTenant(token); tid != "" {
56						tenantID = tid
57					}
58				}
59			}
60	
61			if tenantID == "" && isAuthDisabled() {
62				slog.Warn("auth disabled — accepting unauthenticated request", "path", r.URL.Path)
63				if tid := r.Header.Get("X-Tenant-ID"); tid != "" {
64					tenantID = tid
65				} else {
66					tenantID = "dev-tenant"
67				}
68			}
69	
70			if tenantID == "" {
71				http.Error(w, "unauthorized", http.StatusUnauthorized)
72				return
73			}
74	
75			ctx := context.WithValue(r.Context(), tenantCtxKey, tenantID)
76			next.ServeHTTP(w, r.WithContext(ctx))
77		})
78	}
