84			return ""
85		}
86	
87		claims, ok := token.Claims.(jwt.MapClaims)
88		if !ok {
89			return ""
90		}
91	
92		if tid, ok := claims["org_id"].(string); ok && tid != "" {
93			return tid
94		}
95		if tid, ok := claims["tenant_id"].(string); ok && tid != "" {
96			return tid
97		}
98		return ""
99	}
